264	        if (!over && !focused) return;
265	      }
266	
267	      switch (e.key) {
268	        case 'ArrowLeft':
269	          e.preventDefault();
270	          handlePrevPage();
271	          break;
272	        case 'ArrowRight':
273	          e.preventDefault();
274	          handleNextPage();
275	          break;
