285	function DocumentPreviewPanel({ documento, documentUrl }: DocumentPreviewPanelProps) {
286	  const [numPages, setNumPages] = useState<number | null>(null);
287	  const [currentPage, setCurrentPage] = useState(1);
288	  const [zoom, setZoom] = useState(1);
289	  const [imageSrc, setImageSrc] = useState<string | null>(null);
290	  const [fileConfig, setFileConfig] = useState<{ url: string; httpHeaders?: Record<string, string> } | null>(null);
291	  const viewerScrollRef = useRef<HTMLDivElement>(null);
292	  const pinchDistanceRef = useRef<number | null>(null);
293	  const dragStartRef = useRef<{ x: number; y: number; scrollLeft: number; scrollTop: number } | null>(null);
294	  const { Document, Page, isLoading, error } = usePdfViewer();
295	
296	  const extension = documento.nome.split('.').pop()?.toLowerCase();
297	  const isPdf = !!documento.content_type?.includes('/pdf') || extension === 'pdf';
298	  const zoomPercent = Math.round(zoom * 100);
299	
300	  useEffect(() => {
301	    setZoom(1);
302	    setCurrentPage(1);
303	  }, [documento.id]);
304	
305	  useEffect(() => {
306	    if (!documentUrl || !isPdf) {
307	      setFileConfig(null);
308	      return;
309	    }
310	
311	    getTokenViaAPI().then((token) => {
312	      setFileConfig({
313	        url: documentUrl,
314	        ...(token ? { httpHeaders: { Authorization: `Bearer ${token}` } } : {}),
315	      });
316	    });
317	  }, [documentUrl, isPdf]);
318	
319	  useEffect(() => {
320	    if (!documentUrl || isPdf) {
321	      setImageSrc(null);
322	      return;
323	    }
324	
325	    let objectUrl: string | null = null;
326	
327	    directApi.get(documentUrl, { responseType: 'blob' }).then(({ data }) => {
328	      objectUrl = URL.createObjectURL(data);
329	      setImageSrc(objectUrl);
330	    });
331	
332	    return () => {
333	      if (objectUrl) URL.revokeObjectURL(objectUrl);
334	    };
335	  }, [documentUrl, isPdf]);
336	
337	  const handlePreviousPage = useCallback(() => {
338	    setCurrentPage((page) => Math.max(page - 1, 1));
339	  }, []);
340	
341	  const handleNextPage = useCallback(() => {
342	    setCurrentPage((page) => Math.min(page + 1, numPages || 1));
343	  }, [numPages]);
344	
345	  const handleZoomOut = useCallback(() => {
346	    setZoom((currentZoom) => Math.max(0.5, Number((currentZoom - 0.15).toFixed(2))));
347	  }, []);
348	
349	  const handleZoomIn = useCallback(() => {
350	    setZoom((currentZoom) => Math.min(2.5, Number((currentZoom + 0.15).toFixed(2))));
351	  }, []);
352	
353	  const handleResetZoom = useCallback(() => {
354	    setZoom(1);
355	  }, []);
356	
357	  const handleDownloadDocument = useCallback(async () => {
358	    if (!documentUrl) return;
359	
360	    const { data: blob } = await directApi.get(documentUrl, { responseType: 'blob' });
361	    const objectUrl = URL.createObjectURL(blob);
362	    const link = document.createElement('a');
363	    link.href = objectUrl;
364	    link.download = documento.nome || 'documento';
365	    document.body.appendChild(link);
366	    link.click();
367	    document.body.removeChild(link);
368	    URL.revokeObjectURL(objectUrl);
369	  }, [documentUrl, documento.nome]);
370	
371	  const handleDocumentDoubleClick = useCallback(() => {
372	    setZoom((currentZoom) => (currentZoom < 1.6 ? 1.75 : 1));
373	  }, []);
374	
375	  const getTouchDistance = useCallback((touches: React.TouchList) => {
376	    const first = touches.item(0);
377	    const second = touches.item(1);
378	    if (!first || !second) return null;
379	
380	    return Math.hypot(first.clientX - second.clientX, first.clientY - second.clientY);
381	  }, []);
382	
383	  const handleTouchStart = useCallback(
384	    (event: React.TouchEvent<HTMLDivElement>) => {
385	      if (event.touches.length !== 2) return;
386	      pinchDistanceRef.current = getTouchDistance(event.touches);
387	    },
388	    [getTouchDistance],
389	  );
390	
391	  const handleTouchMove = useCallback(
392	    (event: React.TouchEvent<HTMLDivElement>) => {
393	      if (event.touches.length !== 2 || !pinchDistanceRef.current) return;
394	
395	      event.preventDefault();
396	      const nextDistance = getTouchDistance(event.touches);
397	      if (!nextDistance) return;
398	
399	      const delta = nextDistance - pinchDistanceRef.current;
400	      if (Math.abs(delta) < 6) return;

