      };
    case 'REPROVADO':
      return {
        bgStyle: { backgroundColor: withAlpha(COLORS.red, 0.05), borderColor: withAlpha(COLORS.red, 0.2) },
        textStyle: { color: COLORS.red },
        barStyle: { backgroundColor: COLORS.red },
        icon: <AlertCircle className="w-6 h-6" style={{ color: COLORS.red }} />
