const humanizeFieldName = (fieldName: string): string => {
  // Retorna label customizado ou converte snake_case para Título Case
  if (FIELD_LABELS[fieldName]) {
    return FIELD_LABELS[fieldName];
  }

  return fieldName
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

function humanizeAnalysisStatus(value?: string | null) {
  if (!value) return 'Sem status';
  return value
    .split('_')
    .filter(Boolean)
    .map((word) => word.charAt(0) + word.slice(1).toLowerCase())
    .join(' ');
}

function AnalysisHistoryList({ history }: { history: DocumentoAnaliseHistorico[] }) {
  if (history.length === 0) {
    return (
      <div className="rounded-2xl border p-6 text-center" style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}>
        <p className="font-nexa text-sm font-bold" style={{ color: COLORS.text }}>Sem histórico salvo</p>
        <p className="mt-1 text-sm font-satoshi" style={{ color: COLORS.textDim }}>
          As próximas execuções finalizadas deste documento aparecerão aqui.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {history.map((item) => {
        const config = getRecommendationConfig(item.recomendacao);
        return (
          <article key={item.id} className="rounded-2xl border p-4 shadow-sm" style={{ backgroundColor: COLORS.card, borderColor: COLORS.border }}>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
              <div className="min-w-0 space-y-1">
                <div className="flex flex-wrap items-center gap-2">
                  <Badge variant="outline" className="rounded-full" style={{ borderColor: COLORS.border, color: COLORS.text }}>
                    Tentativa {item.tentativa_numero ?? item.id}
                  </Badge>
                  <Badge variant="outline" className="rounded-full" style={{ borderColor: withAlpha(config.textStyle.color, 0.24), color: config.textStyle.color }}>
                    {item.recomendacao || humanizeAnalysisStatus(item.status)}
                  </Badge>
                  {typeof item.confianca === 'number' ? (
                    <span className="text-xs font-satoshi font-semibold" style={{ color: COLORS.textDim }}>
                      {item.confianca.toFixed(0)}% confiança
                    </span>
                  ) : null}
                </div>
                <p className="text-sm font-satoshi leading-relaxed" style={{ color: COLORS.text }}>
                  {item.resumo || item.erro || 'Sem resumo registrado para esta execução.'}
                </p>
              </div>
              <span className="shrink-0 text-xs font-satoshi" style={{ color: COLORS.textDim }}>
                {new Date(item.criado_em).toLocaleString('pt-BR')}
              </span>
            </div>

            {item.problemas?.length ? (
              <div className="mt-3 rounded-xl border p-3" style={{ backgroundColor: withAlpha(COLORS.red, 0.04), borderColor: withAlpha(COLORS.red, 0.14) }}>
                <p className="mb-2 text-xs font-bold uppercase tracking-widest" style={{ color: COLORS.red }}>Problemas</p>
                <ul className="space-y-1">
                  {item.problemas.slice(0, 4).map((problema, index) => (
                    <li key={`${item.id}-${index}`} className="text-sm font-satoshi" style={{ color: COLORS.redDim || COLORS.red }}>
                      {problema}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </article>
        );
      })}
    </div>
  );
}

interface DocumentPreviewPanelProps {
