'use client';

import { AIAnalysisModal } from '@/app/comercial/aprovacao-documentos/_components/AIAnalysisModal';
import { DocumentCommentsButton } from '@/components/CRM/DocumentCommentsButton';
import ImgDocVisualizer from '@/components/Modals/BrokersDocs/ImgDocVizualizer';
import { PDFViewerModal } from '@/components/Modals/PDFViewerModal';
import { Input } from '@/components/ui/input';
import { ProductSelect } from '@/design-system';
import { DocStatus } from '@/enums/docStatus.enum';
import { isUserMasterOrDev } from '@/functions/rulesVerification';
import { usePdfViewer } from '@/hooks/usePdfViewer';
import { Documento, DocumentoAnalise } from '@/interfaces/IDocumento';
import { cn } from '@/lib/utils';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { DocCardProps } from '@/types/broker';
import { directApi, getTokenViaAPI } from '@/utils/api';
import {
    BookOpenText,
    Copy,
    Download,
    FileText,
    FileX,
    Loader,
    LoaderCircle,
    Loader2,
    Pencil,
    Sparkles,
    Trash2,
    Upload,
} from 'lucide-react';
import Image from 'next/image';
import { useEffect, useRef, useState } from 'react';
import {
    bentoDocCardClass,
    bentoDocCardEmptyPreviewClass,
    bentoDocCardFooterClass,
    bentoDocCardHeaderClass,
    bentoDocCardHeaderMainClass,
    bentoDocCardIconBtnAiClass,
    bentoDocCardIconBtnClass,
    bentoDocCardIconBtnDangerClass,
    bentoDocCardIconWrapClass,
    bentoDocCardPreviewClass,
    bentoDocCardPreviewInnerClass,
    bentoDocCardPreviewOverlayClass,
    bentoDocCardStatusPillClass,
    bentoDocCardStatusSelectTriggerClass,
    bentoDocCardSubtitleClass,
    bentoDocCardTitleClass,
    bentoDocCardTitleWrapClass,
    bentoDocCardToolbarActionsClass,
    bentoDocCardToolbarClass,
    bentoDocCardUploadBtnClass,
} from './bentoCedenteClasses';

function statusLabel(status?: string) {
    if (status === 'APROVADO') return 'Aprovado';
    if (status === 'REPROVADO') return 'Reprovado';
    return 'Pendente';
}

const DOC_STATUS_OPTIONS = Object.values(DocStatus).map((status) => ({
    value: status,
    label: statusLabel(status),
}));

function DocumentBentoPreview({ url, documentType }: { url: string; documentType: string }) {
    const previewRef = useRef<HTMLDivElement>(null);
    const { isLoaded, isLoading, error, Document, Page } = usePdfViewer();
    const [previewWidth, setPreviewWidth] = useState(160);
    const [pdfConfig, setPdfConfig] = useState<{
        url: string;
        httpHeaders?: Record<string, string>;
    } | null>(null);
    const [imageSrc, setImageSrc] = useState<string | null>(null);
    const [fetchLoading, setFetchLoading] = useState(true);
    const [fetchError, setFetchError] = useState(false);

    useEffect(() => {
        const element = previewRef.current;
        if (!element) return;

        const observer = new ResizeObserver(([entry]) => {
            setPreviewWidth(Math.max(100, Math.floor(entry.contentRect.width - 16)));
        });

        observer.observe(element);
        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (!url || !documentType) return;
        setFetchLoading(true);
        setFetchError(false);

        if (documentType === 'pdf') {
            getTokenViaAPI().then((token) => {
                setPdfConfig({
                    url,
                    ...(token ? { httpHeaders: { Authorization: `Bearer ${token}` } } : {}),
                });
                setFetchLoading(false);
            });
        } else {
            directApi
                .get(url, { responseType: 'blob' })
                .then(({ data: blob }) => {
                    setImageSrc(URL.createObjectURL(blob));
                    setFetchLoading(false);
                })
                .catch(() => {
                    setFetchError(true);
                    setFetchLoading(false);
                });
        }
    }, [url, documentType]);

    const previewShell = (content: React.ReactNode) => (
        <div ref={previewRef} className={bentoDocCardPreviewInnerClass}>
            {content}
        </div>
    );

    if (isLoading || fetchLoading) {
        return previewShell(
            <div className={bentoDocCardEmptyPreviewClass}>
                <Loader className="size-6 animate-spin" />
                <span className="text-xs">Carregando prévia…</span>
            </div>,
        );
    }

    if (error || fetchError || !isLoaded) {
        return previewShell(
            <div className={bentoDocCardEmptyPreviewClass}>
                <FileX className="size-10 opacity-40" />
                <span className="text-xs">Prévia indisponível</span>
            </div>,
        );
    }

    if (documentType === 'pdf' && pdfConfig && Document && Page) {
        return previewShell(
            <Document file={pdfConfig} loading={<Loader className="size-6 animate-spin" />}>
                <Page
                    pageNumber={1}
                    width={previewWidth}
                    renderTextLayer={false}
                    renderAnnotationLayer={false}
                />
            </Document>,
        );
    }

    return previewShell(
        <Image
            src={imageSrc ?? ''}
            alt="Prévia do documento"
            width={previewWidth}
            height={Math.round(previewWidth * 1.35)}
            className="max-h-full max-w-full object-contain"
        />,
    );
}

type DocumentsBentoDocCardProps = DocCardProps & { className?: string };

export function DocumentsBentoDocCard({
    idEsteira,
    title,
    subtitle,
    docInfo,
    functions,
    loadingStates,
    className,
    loadingKey,
    exigenciaDocumentalId,
}: DocumentsBentoDocCardProps) {
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const userData = useUserInfoStore((store) => store.data);
    const slotLoadingKey = loadingKey || docInfo.docType;
    const inputId = `bento-upload-${slotLoadingKey}`;

    const [isPDFModalOpen, setIsPDFModalOpen] = useState(false);
    const [isImgVignetteOpen, setIsImgVignetteOpen] = useState(false);
    const [isAIModalOpen, setIsAIModalOpen] = useState(false);

    const docFormat = docInfo.docContentType?.endsWith('pdf') ? 'pdf' : 'img';
    const canApproveDocument = isUserMasterOrDev(userData.role) || isCoordenadorOrMaster;
    const hasFinishedAiAnalysis =
        docInfo.analise?.status === 'CONCLUIDO' || docInfo.analise?.status === 'ERRO';
    const isAiProcessing = docInfo.analise?.status === 'PROCESSANDO';

    const modalAnalise: DocumentoAnalise | null = docInfo.analise
        ? {
              id: docInfo.id,
              status: docInfo.analise.status,
              recomendacao: docInfo.analise.recomendacao ?? null,
              confianca: docInfo.analise.confianca ?? null,
              campos_extraidos: docInfo.analise.campos_extraidos ?? {},
              problemas: docInfo.analise.problemas ?? [],
              sugestoes: docInfo.analise.sugestoes ?? [],
              resumo: docInfo.analise.resumo ?? '',
              modelo_ia: docInfo.analise.modelo_ia ?? '',
              processado_em: null,
              auto_aprovado: docInfo.analise.auto_aprovado ?? false,
              auto_rejeitado:
                  docInfo.analise.recomendacao === 'REPROVADO' &&
                  !(docInfo.analise.auto_aprovado ?? false),
              erro: docInfo.analise.erro ?? '',
              created_at: '',
              updated_at: '',
          }
        : null;

    const modalDocumento: Documento = {
        id: docInfo.id,
        esteiras: [],
        ordem_na_esteira: 0,
        nome: docInfo.name,
        content_type: docInfo.docContentType ?? '',
        has_file: !!docInfo.docDownloadUrl,
        download_url: docInfo.docDownloadUrl ?? null,
        stream_url: docInfo.docStreamUrl ?? null,
        status: docInfo.docStatus ?? 'PENDENTE',
        analise_ia_pendente_revisao_manual: false,
        data_documento: '',
        ordem: 0,
        tipo: docInfo.docType,
        vinculos_count: 0,
        processos_count: 0,
        recursos_count: 0,
        esteiras_count: 0,
        analise: modalAnalise ?? undefined,
        created_at: '',
        updated_at: '',
    };

    function handleOpenVisualizationModal() {
        if (docFormat === 'pdf') setIsPDFModalOpen(true);
        else setIsImgVignetteOpen(true);
    }

    if (!docInfo.docDownloadUrl) {
        return (
            <article
                className={bentoDocCardClass({
                    status: 'PENDENTE',
                    empty: true,
                    className,
                })}
            >
                <header className={bentoDocCardHeaderClass}>
                    <span className={bentoDocCardIconWrapClass}>
                        <FileText className="size-4" />
                    </span>
                    <div className={bentoDocCardHeaderMainClass}>
                        <div className={bentoDocCardTitleWrapClass}>
                            <p className={bentoDocCardTitleClass} title={title}>
                                {title}
                            </p>
                            {subtitle ? (
                                <p className={bentoDocCardSubtitleClass} title={subtitle}>
                                    {subtitle}
                                </p>
                            ) : null}
                        </div>
                        <span className={bentoDocCardStatusPillClass('PENDENTE')}>Pendente</span>
                    </div>
                </header>

                <div className={bentoDocCardPreviewClass}>
                    <div className={bentoDocCardPreviewInnerClass}>
                        <div className={bentoDocCardEmptyPreviewClass}>
                            <Upload className="size-9 opacity-35" />
                            <span className="text-xs">Nenhum arquivo enviado</span>
                        </div>
                    </div>
                </div>

                <div className={bentoDocCardFooterClass}>
                    <label
                        htmlFor={inputId}
                        className={cn(
                            bentoDocCardUploadBtnClass,
                            loadingStates.fetch[slotLoadingKey] && 'pointer-events-none opacity-60',
                        )}
                    >
                        <Input
                            id={inputId}
                            type="file"
                            className="sr-only"
                            accept=".jpg,.jpeg,.png,.gif,.webp,.pdf"
                            onChange={(e) =>
                                functions.handleDoc(e, idEsteira, {
                                    name: docInfo.name,
                                    type: docInfo.docType,
                                    ...(exigenciaDocumentalId != null
                                        ? {
                                              exigencia_documental_id: exigenciaDocumentalId,
                                              loadingKey: slotLoadingKey,
                                          }
                                        : {}),
                                })
                            }
                        />
                        {loadingStates.fetch[slotLoadingKey] ? (
                            <LoaderCircle className="size-4 animate-spin" />
                        ) : (
                            <>
                                <Upload className="size-4" />
                                Selecionar documento
                            </>
                        )}
                    </label>
                </div>
            </article>
        );
    }

    return (
        <article
            className={bentoDocCardClass({
                status: docInfo.docStatus,
                aiReady: hasFinishedAiAnalysis,
                className,
            })}
        >
            <header className={bentoDocCardHeaderClass}>
                <span className={bentoDocCardIconWrapClass}>
                    <FileText className="size-4" />
                </span>
                <div className={bentoDocCardHeaderMainClass}>
                    <div className={bentoDocCardTitleWrapClass}>
                        <p className={bentoDocCardTitleClass} title={title}>
                            {title}
                        </p>
                        {subtitle ? (
                            <p className={bentoDocCardSubtitleClass} title={subtitle}>
                                {subtitle}
                            </p>
                        ) : null}
                    </div>
                    <div className="flex shrink-0 items-center gap-1.5">
                        {loadingStates.status[docInfo.docType] ? (
                            <LoaderCircle className="size-3.5 animate-spin opacity-60" />
                        ) : null}
                        <span className={bentoDocCardStatusPillClass(docInfo.docStatus)}>
                            {statusLabel(docInfo.docStatus)}
                        </span>
                    </div>
                </div>
            </header>

            <div className={bentoDocCardPreviewClass}>
                <button
                    type="button"
                    className={bentoDocCardPreviewOverlayClass}
                    onClick={handleOpenVisualizationModal}
                    aria-label={`Visualizar ${title}`}
                >
                    <BookOpenText className="size-4" />
                    Visualizar
                </button>
                <DocumentBentoPreview url={docInfo.docDownloadUrl} documentType={docFormat} />
            </div>

            <div className={bentoDocCardFooterClass}>
                <div className={bentoDocCardToolbarClass}>
                    <ProductSelect
                        fullWidth
                        size="sm"
                        className="min-w-0 flex-1"
                        triggerClassName={bentoDocCardStatusSelectTriggerClass}
                        value={docInfo.docStatus || DocStatus.ANALISE}
                        options={DOC_STATUS_OPTIONS}
                        disabled={!canApproveDocument || loadingStates.status[docInfo.docType]}
                        onChange={(value) =>
                            functions.changeDocStatus(value, docInfo.docType, docInfo.id)
                        }
                        aria-label={`Status de ${title}`}
                    />

                    <div className={bentoDocCardToolbarActionsClass}>
                        <label
                            htmlFor={`bento-replace-${slotLoadingKey}-${docInfo.id}`}
                            title="Alterar arquivo"
                            className={cn(
                                bentoDocCardIconBtnClass,
                                (loadingStates.fetch[slotLoadingKey] ||
                                    loadingStates.status[slotLoadingKey]) &&
                                    'pointer-events-none opacity-60',
                            )}
                        >
                            <Input
                                id={`bento-replace-${slotLoadingKey}-${docInfo.id}`}
                                type="file"
                                className="sr-only"
                                accept=".jpg,.jpeg,.png,.gif,.webp,.pdf"
                                disabled={
                                    Boolean(loadingStates.fetch[slotLoadingKey]) ||
                                    Boolean(loadingStates.status[slotLoadingKey])
                                }
                                onChange={(e) =>
                                    functions.handleDoc(e, idEsteira, {
                                        name: docInfo.name,
                                        type: docInfo.docType,
                                        ...(exigenciaDocumentalId != null
                                            ? {
                                                  exigencia_documental_id: exigenciaDocumentalId,
                                                  loadingKey: slotLoadingKey,
                                              }
                                            : {}),
                                    })
                                }
                            />
                            {loadingStates.fetch[slotLoadingKey] ? (
                                <LoaderCircle className="animate-spin" />
                            ) : (
                                <Pencil />
                            )}
                        </label>

                        <DocumentCommentsButton
                            documentId={docInfo.id}
                            documentName={docInfo.name || title}
                            compact
                            className={cn(
                                bentoDocCardIconBtnClass,
                                'h-[30px]! w-[30px]! min-w-[30px]! rounded-[8px]! border! p-0!',
                            )}
                        />

                        {canApproveDocument ? (
                            <button
                                type="button"
                                title="Análise IA"
                                disabled={isAiProcessing}
                                onClick={() => setIsAIModalOpen(true)}
                                className={cn(bentoDocCardIconBtnClass, bentoDocCardIconBtnAiClass)}
                            >
                                {isAiProcessing ? (
                                    <Loader2 className="animate-spin" />
                                ) : (
                                    <Sparkles />
                                )}
                            </button>
                        ) : (
                            <button
                                type="button"
                                title="Baixar"
                                disabled={!docInfo.docDownloadUrl}
                                onClick={() =>
                                    functions.downloadDoc({
                                        download_url: docInfo.docDownloadUrl as string,
                                        nome: docInfo.name || title,
                                        content_type: docInfo.docContentType ?? '',
                                    })
                                }
                                className={bentoDocCardIconBtnClass}
                            >
                                <Download />
                            </button>
                        )}

                        <button
                            type="button"
                            title="Copiar link"
                            onClick={() => functions.copyLink(docInfo.docDownloadUrl as string)}
                            className={bentoDocCardIconBtnClass}
                        >
                            <Copy />
                        </button>

                        <button
                            type="button"
                            title="Desvincular"
                            disabled={
                                loadingStates.unlink[docInfo.docType] ||
                                loadingStates.status[docInfo.docType]
                            }
                            onClick={() => functions.removeDoc(docInfo.id, docInfo.docType)}
                            className={cn(bentoDocCardIconBtnClass, bentoDocCardIconBtnDangerClass)}
                        >
                            {loadingStates.unlink[docInfo.docType] ? (
                                <LoaderCircle className="animate-spin" />
                            ) : (
                                <Trash2 />
                            )}
                        </button>
                    </div>
                </div>
            </div>

            <PDFViewerModal
                fileUrl={docInfo.docDownloadUrl}
                open={isPDFModalOpen}
                onOpenChange={setIsPDFModalOpen}
                fileName={docInfo.name}
            />
            {isImgVignetteOpen ? (
                <ImgDocVisualizer
                    onClose={() => setIsImgVignetteOpen(false)}
                    url={docInfo.docDownloadUrl}
                    fileName={docInfo.name}
                />
            ) : null}
            {isAIModalOpen && canApproveDocument ? (
                <AIAnalysisModal
                    isOpen={isAIModalOpen}
                    onClose={() => setIsAIModalOpen(false)}
                    documento={modalDocumento}
                    analise={modalAnalise}
                    showDocumentActions={canApproveDocument}
                    showAuditFeedback={canApproveDocument}
                    onApprove={async () => {
                        await functions.changeDocStatus('APROVADO', docInfo.docType, docInfo.id);
                        setIsAIModalOpen(false);
                    }}
                    onReject={async () => {
                        await functions.changeDocStatus('REPROVADO', docInfo.docType, docInfo.id);
                        setIsAIModalOpen(false);
                    }}
                />
            ) : null}
        </article>
    );
}

