'use client';
import ImgDocVisualizer from '@/components/Modals/BrokersDocs/ImgDocVizualizer';
import { DocumentCommentsButton } from '@/components/CRM/DocumentCommentsButton';
import { DocumentPreviewer } from '@/components/Documents/DocumentPreviewer';
import { PDFViewerModal } from '@/components/Modals/PDFViewerModal';
import { AIAnalysisModal } from '@/app/comercial/aprovacao-documentos/_components/AIAnalysisModal';
import { Button } from '@/components/ui/button';
import {
    Card,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import { DocStatus } from '@/enums/docStatus.enum';
import { canManageDocuments } from '@/functions/rulesVerification';
import { cn } from '@/lib/utils';
import { useUserInfoStore } from '@/store/userInfo';
import { DocCardProps, EmptyBrokerDocCardProps } from '@/types/broker';
import { Documento, DocumentoAnalise } from '@/interfaces/IDocumento';
import {
    BookOpenText,
    Copy,
    Download,
    FileX,
    LoaderCircle,
    Pencil,
    Trash2,
    Upload,
    Loader2,
    Sparkles,
} from 'lucide-react';
import { useState } from 'react';

export default function BrokerDocCard({
    idEsteira,
    title,
    subtitle,
    docInfo,
    functions,
    loadingStates,
    className,
    buttonWithLabel = false,
    highlightNewRequirement = false,
    loadingKey,
    exigenciaDocumentalId,
}: DocCardProps & { className?: string }) {
    const permissions = useUserInfoStore((store) => store.permissions);
    const slotLoadingKey = loadingKey || docInfo.docType;
    const inputId = `broker-doc-${slotLoadingKey}`;

    const [isPDFModalOpen, setIsPDFModalOpen] = useState<boolean>(false);
    const [isImgVignetteOpen, setIsImgVignetteOpen] = useState<boolean>(false);
    const [isAIModalOpen, setIsAIModalOpen] = useState<boolean>(false);

    const docFormat = docInfo.docContentType?.endsWith('pdf') ? 'pdf' : 'img';

    const canApproveDocument = canManageDocuments(permissions);

    const modalAnalise: DocumentoAnalise | null = docInfo.analise
        ? {
              id: docInfo.id,
              status: docInfo.analise.status,
              recomendacao: docInfo.analise.recomendacao ?? null,
              confianca: docInfo.analise.confianca ?? null,
              campos_extraidos: docInfo.analise.campos_extraidos ?? {},
              problemas: docInfo.analise.problemas ?? [],
              sugestoes: docInfo.analise.sugestoes ?? [],
              resumo: docInfo.analise.resumo ?? '',
              modelo_ia: docInfo.analise.modelo_ia ?? '',
              processado_em: null,
              auto_aprovado: docInfo.analise.auto_aprovado ?? false,
              auto_rejeitado:
                  docInfo.analise.recomendacao === 'REPROVADO' &&
                  !(docInfo.analise.auto_aprovado ?? false),
              erro: docInfo.analise.erro ?? '',
              created_at: '',
              updated_at: '',
          }
        : null;
    const modalDocumento: Documento = {
        id: docInfo.id,
        esteiras: [],
        ordem_na_esteira: 0,
        nome: docInfo.name,
        content_type: docInfo.docContentType ?? '',
        has_file: !!docInfo.docDownloadUrl,
        download_url: docInfo.docDownloadUrl ?? null,
        stream_url: docInfo.docStreamUrl ?? null,
        status: docInfo.docStatus ?? 'PENDENTE',
        analise_ia_pendente_revisao_manual: false,
        data_documento: '',
        ordem: 0,
        tipo: docInfo.docType,
        vinculos_count: 0,
        processos_count: 0,
        recursos_count: 0,
        esteiras_count: 0,
        analise: modalAnalise ?? undefined,
        created_at: '',
        updated_at: '',
    };
    const analiseStatus = docInfo.analise?.status;
    const hasFinishedAiAnalysis = analiseStatus === 'CONCLUIDO' || analiseStatus === 'ERRO';

    function handleOpenVisualizationModal() {
        if (docFormat === 'pdf') {
            setIsPDFModalOpen(true);
        } else {
            setIsImgVignetteOpen(true);
        }
    }

    if (!docInfo.docDownloadUrl)
        return (
            <EmptyBrokerDocCard
                idEsteira={idEsteira}
                title={title}
                subtitle={subtitle}
                handleDocument={functions?.handleDoc}
                isUploading={Boolean(loadingStates.fetch[slotLoadingKey])}
                docInfo={docInfo}
                loadingKey={slotLoadingKey}
                exigenciaDocumentalId={exigenciaDocumentalId}
                highlightNewRequirement={highlightNewRequirement}
            />
        );

    return (
        <Card
            id="tour-doc-card"
            className={cn(
                'flex w-full flex-col border shadow-default transition-colors duration-200',
                hasFinishedAiAnalysis
                    ? 'border-sky-200/90 bg-sky-50/50 dark:border-sky-800/50 dark:bg-sky-950/30'
                    : highlightNewRequirement
                      ? 'border-amber-300 bg-amber-50/40 ring-1 ring-amber-200/80 dark:border-amber-700 dark:bg-amber-950/20'
                      : 'border-stroke dark:border-form-strokedark',
                className,
            )}
        >
            <CardHeader className="space-y-0 px-4 pb-2 pt-4">
                <CardTitle
                    className={`flex items-center gap-2 text-subtitle ${subtitle ? 'mb-0' : 'mb-4'}`}
                >
                    <p className="max-w-56 flex-1 truncate text-lg font-medium" title={title}>
                        {title}
                    </p>
                    {highlightNewRequirement ? (
                        <span className="shrink-0 rounded-full border border-amber-300 bg-amber-100 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber-800">
                            Novo
                        </span>
                    ) : null}

                    {loadingStates.status[slotLoadingKey] && (
                        <LoaderCircle size={18} className="animate-spin opacity-50" />
                    )}
                </CardTitle>
                {subtitle && (
                    <CardDescription className="m-0 text-xs font-medium text-muted-foreground">
                        ({subtitle})
                    </CardDescription>
                )}
            </CardHeader>
            <CardContent className="px-4 pb-4">
                <div className="flex flex-col gap-4">
                    <div id="tour-doc-preview" className="full group relative h-[165px]">
                        <div
                            role="button"
                            onClick={handleOpenVisualizationModal}
                            className="absolute inset-0 z-3 flex cursor-pointer items-center justify-center gap-2 rounded-lg bg-black-2/30 opacity-0 group-hover:opacity-100"
                        >
                            <BookOpenText size={16} className="text-snow" />
                            <p className="text-sm font-medium text-snow">Visualizar</p>
                        </div>
                        <div className="flex max-h-[165px] w-full flex-col gap-3 rounded-lg border border-stroke bg-stroke p-1 dark:border-form-strokedark dark:bg-form-strokedark">
                            <div className="relative flex h-30 w-full flex-col items-center justify-center overflow-hidden rounded-md bg-boxdark-2 ">
                                <DocumentPreviewer
                                    url={docInfo.docDownloadUrl}
                                    documentType={docFormat}
                                />
                            </div>
                            <p
                                title={docInfo.name}
                                className="mx-auto max-w-[170px] truncate text-xs"
                            >
                                {docInfo.name}
                            </p>
                        </div>
                    </div>

