'use client';

import { AIAnalysisModal } from '@/app/comercial/aprovacao-documentos/_components/AIAnalysisModal';
import { ACCEPTED_DOCUMENT_EXTENSIONS } from '@/app/crm/broker/[id]/_components/utils/validateDocumentExtension';
import ImgDocVisualizer from '@/components/Modals/BrokersDocs/ImgDocVizualizer';
import { PDFViewerModal } from '@/components/Modals/PDFViewerModal';
import { DocumentPreviewer } from '@/components/Documents/DocumentPreviewer';
import { Input } from '@/components/ui/input';
import {
    brokerSlotLoadingKey,
    brokerSlotToDocType,
    brokerSlotUploadInfo,
    type BrokerDocumentUploadInfo,
} from '@/functions/broker/broker-document-exigencias';
import type { BrokerDocumentCatalogItem } from '@/functions/broker/groupBrokerDocumentCatalog';
import { canManageDocuments } from '@/functions/rulesVerification';
import { Documento, DocumentoAnalise } from '@/interfaces/IDocumento';
import { cn } from '@/lib/utils';
import { useUserInfoStore } from '@/store/userInfo';
import type { loadingDocStates } from '@/types/broker';
import { Check, Clock, Download, LoaderCircle, RefreshCw, Sparkles, Upload } from 'lucide-react';
import { useId, useState } from 'react';

/** Largura da miniatura do documento anexado (alinha com `w-14`). */
const PREVIEW_THUMB_WIDTH_PX = 56;

interface GavetaDocumentoRowProps {
    item: BrokerDocumentCatalogItem;
    esteiraId: number;
    loadingStates: loadingDocStates;
    onUpload: (
        event: React.ChangeEvent<HTMLInputElement>,
        esteiraId: number,
        documentInfo: BrokerDocumentUploadInfo,
    ) => Promise<void>;
    onChangeStatus: (status: string, docType: string, docId: number) => Promise<void>;
    onDownload: (document: {
        download_url: string;
        nome: string;
        content_type: string;
    }) => Promise<void>;
}

function resolveUploadInfo(item: BrokerDocumentCatalogItem): BrokerDocumentUploadInfo {
    if (item.slot) return brokerSlotUploadInfo(item.slot);
    return { name: item.label, type: item.document?.tipo || 'OUTROS' };
}

function resolveLoadingKey(item: BrokerDocumentCatalogItem): string {
    if (item.slot) return brokerSlotLoadingKey(item.slot);
    return item.id;
}

function resolveDocType(item: BrokerDocumentCatalogItem): string {
    if (item.slot) return brokerSlotToDocType(item.slot);
    return item.document?.tipo || 'OUTROS';
}

function hasAttachedFile(item: BrokerDocumentCatalogItem): boolean {
    return Boolean(item.document?.download_url || item.document?.has_file);
}

function buildModalAnalise(item: BrokerDocumentCatalogItem): DocumentoAnalise | null {
    const analise = item.document?.analise;
    if (!analise || !item.document) return null;

    return {
        id: item.document.id,
        status: analise.status,
        recomendacao: analise.recomendacao ?? null,
        confianca: analise.confianca ?? null,
        campos_extraidos: analise.campos_extraidos ?? {},
        problemas: analise.problemas ?? [],
        sugestoes: analise.sugestoes ?? [],
        resumo: analise.resumo ?? '',
        modelo_ia: analise.modelo_ia ?? '',
        processado_em: null,
        auto_aprovado: analise.auto_aprovado ?? false,
        auto_rejeitado: analise.recomendacao === 'REPROVADO' && !(analise.auto_aprovado ?? false),
        erro: analise.erro ?? '',
        created_at: '',
        updated_at: '',
    };
}

function buildModalDocumento(
    item: BrokerDocumentCatalogItem,
    analise: DocumentoAnalise | null,
): Documento {
    return {
        id: item.document?.id ?? 0,
        esteiras: [],
        ordem_na_esteira: 0,
        nome: item.document?.nome || item.label,
        content_type: item.document?.content_type ?? '',
        has_file: hasAttachedFile(item),
        download_url: item.document?.download_url ?? null,
        stream_url: item.document?.stream_url ?? null,
        status: item.document?.status ?? 'PENDENTE',
        analise_ia_pendente_revisao_manual: false,
        data_documento: '',
        ordem: 0,
        tipo: resolveDocType(item),
        vinculos_count: 0,
        processos_count: 0,
        recursos_count: 0,
        esteiras_count: 0,
        analise: analise ?? undefined,
        created_at: '',
        updated_at: '',
    };
}

export function GavetaDocumentoRow({
    item,
    esteiraId,
    loadingStates,
    onUpload,
    onChangeStatus,
    onDownload,
}: GavetaDocumentoRowProps) {
    const inputId = useId();
    const permissions = useUserInfoStore((store) => store.permissions);
    const canApproveDocument = canManageDocuments(permissions);
    const [isPdfOpen, setIsPdfOpen] = useState(false);
    const [isImageOpen, setIsImageOpen] = useState(false);
    const [isAiOpen, setIsAiOpen] = useState(false);

    const attached = hasAttachedFile(item);
    const isRejected = item.document?.status === 'REPROVADO';
    const isApproved = item.document?.status === 'APROVADO';
    const downloadUrl = item.document?.download_url;
    const isPdf = item.document?.content_type?.includes('pdf');
    const isAiProcessing = item.document?.analise?.status === 'PROCESSANDO';
    const modalAnalise = buildModalAnalise(item);
    const modalDocumento = buildModalDocumento(item, modalAnalise);
    const uploadInfo = resolveUploadInfo(item);
    const docType = resolveDocType(item);
    const loadingKey = resolveLoadingKey(item);
    const isBusy = Boolean(loadingStates.fetch[loadingKey]);

    const subtitle = isRejected
        ? 'Envie outra versão deste arquivo'
        : attached
          ? item.document?.nome || item.subtitle
          : item.subtitle || 'anexar arquivo';

    const ctaLabel = isRejected
        ? 'enviar'
        : isApproved
          ? 'aprovado'
          : attached
            ? 'aguardando aprovação'
            : 'anexar';

    function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
        void onUpload(event, esteiraId, uploadInfo);
    }

    function handleOpenPreview() {
        if (!downloadUrl) return;
        if (isPdf) setIsPdfOpen(true);
        else setIsImageOpen(true);
    }

    function handleDownload() {
        const document = item.document;
        if (!document?.download_url) return;
        void onDownload({
            download_url: document.download_url,
            nome: document.nome || item.label,
            content_type: document.content_type ?? '',
        });
    }

    const Icone = isBusy
        ? LoaderCircle
        : isRejected
          ? RefreshCw
          : isApproved
            ? Check
            : attached
              ? Clock
              : Upload;

    return (
        <div
            className={cn(
                'flex w-full items-center gap-3 rounded-xl border px-3 py-3',
                isRejected
                    ? 'border-amber-300 bg-amber-50 dark:border-amber-500/40 dark:bg-amber-950/40'
                    : isApproved
                      ? 'border-emerald-200 bg-emerald-50 dark:border-emerald-900 dark:bg-emerald-950/40'
                      : 'border-celer-line bg-celer-paper hover:border-celer-blue/40',
            )}
        >
            {attached && downloadUrl ? (
                <button
                    type="button"
                    onClick={handleOpenPreview}
                    title="Visualizar documento"
                    className={cn(
                        'relative h-16 w-14 shrink-0 overflow-hidden rounded-[9px] border bg-celer-panel',
                        isRejected
                            ? 'border-amber-300 dark:border-amber-500/40'
                            : isApproved
                              ? 'border-emerald-200 dark:border-emerald-900'
                              : 'border-celer-line hover:border-celer-blue/40',
                    )}
                >
                    <span className="pointer-events-none absolute inset-0 flex items-start justify-center [&_p]:hidden">
                        <DocumentPreviewer
                            url={downloadUrl}
                            documentType={isPdf ? 'pdf' : 'img'}
                            pageWidth={PREVIEW_THUMB_WIDTH_PX}
                            documentId={item.document?.id}
                        />
                    </span>
                    <span
                        className={cn(
                            'absolute bottom-1 right-1 grid size-4 place-items-center rounded-full text-white shadow',
                            isRejected
                                ? 'bg-amber-500'
                                : isApproved
                                  ? 'bg-emerald-500'
                                  : 'bg-celer-blue',
                        )}
                        aria-hidden
                    >
                        <Icone className={cn('size-2.5', isBusy && 'animate-spin')} />
                    </span>
                </button>
            ) : (
                <span
                    className={cn(
                        'grid size-[30px] shrink-0 place-items-center rounded-[9px] text-white',
                        isRejected
                            ? 'bg-amber-500 shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(217,119,6,0.4)]'
                            : isApproved
                              ? 'bg-emerald-500 shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(5,150,105,0.4)]'
                              : attached
                                ? 'bg-celer-blue shadow-[inset_0_1px_0_rgba(255,255,255,0.35),0_1px_2px_rgba(28,100,242,0.4)]'
                                : 'bg-celer-panel text-celer-muted shadow-[inset_0_1px_2px_rgba(15,23,42,0.12),inset_0_-1px_0_rgba(255,255,255,0.5)] dark:shadow-[inset_0_1px_2px_rgba(0,0,0,0.35)]',
                    )}
                    aria-hidden
                >
                    <Icone className={cn('size-3.5', isBusy && 'animate-spin')} />
                </span>
            )}

'use client';

import { DocumentPreviewer } from '@/components/Documents/DocumentPreviewer';
import { cn } from '@/lib/utils';
import { Eye, FileText, Paperclip, Search } from 'lucide-react';
import type {
    IAnaliseRessalvasIntegraDocumentoSlot,
    IAnaliseRessalvasIntegraModalHandlers,
    IAnaliseRessalvasIntegraModalUI,
    IAnaliseRessalvasIntegraRessalvaItem,
} from '../../../ViewModels/DueIntegra/useViewModelAnaliseRessalvasIntegraModal';
import { integraLabelCapsClass, integraMutedTextClass } from '../../shared/integra/integra-styles';

const PREVIEW_PAGE_WIDTH = 300;

export interface IAnaliseRessalvasIntegraModalViewProps {
    ui: IAnaliseRessalvasIntegraModalUI;
    handlers: IAnaliseRessalvasIntegraModalHandlers;
}

function AnaliseRessalvaSidebarItem({
    item,
    isSelected,
    onSelect,
}: {
    item: IAnaliseRessalvasIntegraRessalvaItem;
    isSelected: boolean;
    onSelect: () => void;
}) {
    return (
        <button
            type="button"
            onClick={onSelect}
            className={cn(
                'flex w-full min-w-0 items-start gap-3 rounded-xl px-3 py-3 text-left transition-colors',
                isSelected
                    ? 'bg-white shadow-[var(--shadow-surface-rest)] dark:bg-boxdark'
                    : 'hover:bg-white/70 dark:hover:bg-boxdark/70',
            )}
            aria-pressed={isSelected}
        >
            <span className="mt-0.5 rounded-lg bg-orange-50 px-2 py-1 font-satoshi text-xs font-bold text-orange-500">
                {item.indexLabel}
            </span>
            <span className="min-w-0 flex-1">
                <span className="block truncate font-satoshi text-sm font-bold text-celer-strong dark:text-foreground">
                    {item.categoryLabel}
                </span>
                <span className="mt-0.5 line-clamp-1 block font-satoshi text-xs text-celer-muted">
                    {item.descriptionPreview}
                </span>
            </span>
        </button>
    );
}

function AnaliseRessalvaDocumentSlot({
    slot,
    onSelect,
}: {
    slot: IAnaliseRessalvasIntegraDocumentoSlot;
    onSelect: () => void;
}) {
    return (
        <div
            className={cn(
                'flex min-w-0 items-center gap-2 rounded-xl border border-celer-line bg-white p-2 transition-colors dark:bg-boxdark',
                slot.isSelected && 'border-celer-blue bg-celer-blue/[0.05] ring-1 ring-celer-blue',
            )}
            data-testid={`analise-ressalva-slot-${slot.slotKey}`}
        >
            <span
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-celer-blue/10 text-celer-blue"
                aria-hidden
            >
                <Paperclip className="h-3.5 w-3.5" />
            </span>
            <span className="min-w-0 flex-1">
                <span className="block truncate font-satoshi text-xs font-semibold text-celer-strong dark:text-foreground">
                    {slot.displayName}
                </span>
                <span className="block font-satoshi text-[10px] font-bold uppercase tracking-[0.08em] text-celer-muted">
                    {slot.extensionLabel}
                </span>
            </span>
            <button
                type="button"
                className={cn(
                    'flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-celer-muted transition-colors hover:bg-celer-blue/10 hover:text-celer-blue',
                    slot.isSelected && 'text-celer-blue',
                )}
                aria-label={`Visualizar ${slot.fileName}`}
                aria-pressed={slot.isSelected}
                onClick={onSelect}
            >
                <Eye className="h-3.5 w-3.5" strokeWidth={1.8} />
            </button>
        </div>
    );
}

function AnaliseRessalvaPreviewPlaceholder() {
    return (
        <div
            className="flex min-h-[260px] flex-1 flex-col items-center justify-center gap-3 rounded-xl border border-dashed border-celer-line bg-celer-panel/40 p-6 text-center"
            data-testid="analise-ressalvas-preview-placeholder"
        >
            <span
                className="flex h-12 w-12 items-center justify-center rounded-2xl bg-celer-blue/10 text-celer-blue"
                aria-hidden
            >
                <FileText className="h-5 w-5" strokeWidth={1.7} />
            </span>
            <p className={cn('max-w-[14rem] text-sm leading-relaxed', integraMutedTextClass())}>
                Selecione um documento para visualizar.
            </p>
        </div>
    );
}

export function AnaliseRessalvasIntegraModalView({
    ui,
    handlers,
}: IAnaliseRessalvasIntegraModalViewProps) {
    return (
        <div className="grid min-h-0 flex-1 grid-cols-1 overflow-hidden lg:grid-cols-[280px_minmax(0,1fr)_minmax(320px,0.9fr)]">
            <aside className="min-h-0 overflow-y-auto bg-boxdark-2 p-4 diligence-filter-tabs-scroll">
                <label className="relative block">
                    <Search
                        className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-celer-muted"
                        aria-hidden
                    />
                    <input
                        value={ui.searchQuery}
                        onChange={(event) => handlers.onSearchChange(event.target.value)}
                        placeholder="Buscar ressalva..."
                        className="h-11 w-full rounded-xl border border-celer-line bg-white pl-9 pr-3 font-satoshi text-sm text-celer-strong outline-none transition-colors placeholder:text-celer-muted focus:border-celer-blue dark:bg-boxdark dark:text-foreground"
                        aria-label="Buscar ressalva"
                    />
                </label>

                <div className="mt-3 space-y-2" data-testid="analise-ressalvas-list">
                    {ui.ressalvas.length > 0 ? (
                        ui.ressalvas.map((item) => (
                            <AnaliseRessalvaSidebarItem
                                key={item.id}
                                item={item}
                                isSelected={item.id === ui.selectedRessalva?.id}
                                onSelect={() => handlers.onSelectRessalva(item.id)}
                            />
                        ))
                    ) : (
                        <p className={cn('px-2 py-6 text-center text-sm', integraMutedTextClass())}>
                            Nenhuma ressalva encontrada.
                        </p>
                    )}
                </div>
            </aside>

            <section className="min-h-0 overflow-y-auto px-8 py-7 diligence-filter-tabs-scroll">
                {ui.selectedRessalva ? (
                    <div className="space-y-7">
                        <div className="space-y-2">
                            <p className={integraLabelCapsClass()}>Categoria</p>
                            <h3 className="font-satoshi text-lg font-bold uppercase tracking-[-0.01em] text-celer-strong dark:text-foreground">
                                {ui.selectedRessalva.categoryLabel}
                            </h3>
                        </div>

                        <div className="space-y-2">
                            <p className={integraLabelCapsClass()}>Descrição</p>
                            <p className="m-0 whitespace-pre-wrap font-satoshi text-sm leading-7 text-celer-strong dark:text-foreground">
                                {ui.selectedRessalva.descriptionPreview}
                            </p>
                        </div>

                        <div className="space-y-3">
                            <p className={integraLabelCapsClass()}>Documentos da ressalva</p>
                            {ui.selectedRessalvaDocumentSlots.length > 0 ? (
                                <div className="space-y-2">
                                    {ui.selectedRessalvaDocumentSlots.map((slot) => (
                                        <AnaliseRessalvaDocumentSlot
                                            key={slot.slotKey}
                                            slot={slot}
                                            onSelect={() => handlers.onSelectDocument(slot.slotKey)}
                                        />
                                    ))}
                                </div>
                            ) : (
                                <p className={cn('pl-4 text-sm', integraMutedTextClass())}>
                                    Nenhum documento anexado
                                </p>
                            )}
                        </div>
                    </div>
                ) : (
                    <p className={cn('py-10 text-center text-sm', integraMutedTextClass())}>
                        Nenhuma ressalva disponível.
                    </p>
                )}
            </section>

            <section
                className="flex min-h-0 flex-col border-t border-celer-line bg-white p-4 dark:bg-boxdark lg:border-l lg:border-t-0"
                aria-label="Pré-visualização do documento da ressalva"
                data-testid="analise-ressalvas-preview"
            >
                <p className="mb-3 font-satoshi text-xs font-semibold text-celer-strong dark:text-foreground">
                    Preview do documento
                </p>
                <div className="flex min-h-[260px] flex-1 items-center justify-center overflow-hidden">
                    {ui.selectedPreview ? (
                        <DocumentPreviewer
                            url={ui.selectedPreview.url}
                            documentType={ui.selectedPreview.documentType}
                            documentId={ui.selectedPreview.documentId}
                            pageWidth={PREVIEW_PAGE_WIDTH}
                        />
                    ) : (
                        <AnaliseRessalvaPreviewPlaceholder />
                    )}
                </div>
            </section>
        </div>
    );
}

