'use client';

import { DocumentPreviewer } from '@/components/Documents/DocumentPreviewer';
import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import { Separator } from '@/components/ui/separator';
import {
    COLORS,
    ProductDialogContent,
    ProductDialogDescription,
    ProductDialogHeader,
    ProductDialogTitle,
    withAlpha,
} from '@/design-system';
import { cn } from '@/lib/utils';
import { Eye, FileText, Gavel, Loader2, Paperclip, Upload, X } from 'lucide-react';
import type { ChangeEvent, ReactNode } from 'react';
import type {
    IDetalhesParteProcessoModalAnexoSlot,
    IDetalhesParteProcessoModalCampo,
    IDetalhesParteProcessoModalViewProps,
} from '../../interfaces/detalhesParteProcessoModal';

const PROCESSO_MODAL_PREVIEW_WIDTH = 240;

interface IDetalhesParteProcessoModalHeaderProps {
    processoNome: string;
    metaLabel: string;
    valorCausaLabel: string;
    onClose: () => void;
}

function DetalhesParteProcessoModalHeader({
    processoNome,
    metaLabel,
    valorCausaLabel,
    onClose,
}: IDetalhesParteProcessoModalHeaderProps) {
    return (
        <ProductDialogHeader
            className="flex flex-row items-center gap-3 space-y-0 px-[18px] py-[15px]"
            style={{ background: COLORS.paper }}
            data-testid="processo-modal-header"
        >
            <span
                className="flex h-[30px] w-[30px] shrink-0 items-center justify-center rounded-lg"
                style={{
                    background: withAlpha(COLORS.brand, 0.14),
                    color: COLORS.brand,
                }}
                data-testid="processo-modal-header-icon"
                aria-hidden
            >
                <Gavel size={16} strokeWidth={1.8} />
            </span>

            <div className="min-w-0 flex-1">
                <ProductDialogTitle className="truncate font-satoshi text-sm font-bold leading-tight">
                    {processoNome}
                </ProductDialogTitle>
                {metaLabel ? (
                    <ProductDialogDescription
                        className="mt-0.5 truncate text-[11px] leading-none"
                        style={{ color: COLORS.textDim }}
                        data-testid="processo-modal-meta"
                    >
                        {metaLabel}
                    </ProductDialogDescription>
                ) : null}
            </div>

            <div className="flex shrink-0 items-center gap-3">
                <div className="text-right" data-testid="processo-modal-valor-causa">
                    <p
                        className="font-satoshi text-[10px] font-bold uppercase tracking-[0.06em]"
                        style={{ color: COLORS.textDim }}
                    >
                        Valor da causa
                    </p>
                    <p
                        className="mt-0.5 font-satoshi text-[13px] font-bold tabular-nums"
                        style={{ color: COLORS.danger }}
                    >
                        {valorCausaLabel}
                    </p>
                </div>

                <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8 shrink-0 text-muted-foreground hover:text-foreground"
                    aria-label="Fechar"
                    onClick={onClose}
                >
                    <X className="h-4 w-4" strokeWidth={1.8} />
                </Button>
            </div>
        </ProductDialogHeader>
    );
}

interface IProcessoModalUploadActionProps {
    id: string;
    label: string;
    accept: string;
    isUploading: boolean;
    onUpload: (file: File) => Promise<void>;
}

function ProcessoModalUploadAction({
    id,
    label,
    accept,
    isUploading,
    onUpload,
}: IProcessoModalUploadActionProps) {
    async function onFileChange(event: ChangeEvent<HTMLInputElement>) {
        const input = event.currentTarget;
        const file = input.files?.[0];
        input.value = '';

        if (file) await onUpload(file);
    }

    return (
        <label
            htmlFor={id}
            aria-disabled={isUploading}
            className={cn(
                'inline-flex h-9 cursor-pointer items-center justify-center gap-2 rounded-lg border px-3 font-satoshi text-xs font-semibold transition-colors',
                isUploading
                    ? 'pointer-events-none opacity-60'
                    : 'hover:border-celer-blue hover:text-celer-blue',
            )}
            style={{ borderColor: COLORS.line, color: COLORS.text }}
        >
            <input
                id={id}
                type="file"
                accept={accept}
                disabled={isUploading}
                className="sr-only"
                onChange={onFileChange}
            />
            {isUploading ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
            ) : (
                <Upload className="h-3.5 w-3.5" aria-hidden />
            )}
            {label}
        </label>
    );
}

interface IProcessoModalPlaceholderProps {
    message: string;
    children?: ReactNode;
}

function ProcessoModalPlaceholder({ message, children }: IProcessoModalPlaceholderProps) {
    return (
        <div
            className="flex min-h-[180px] flex-col items-center justify-center gap-4 px-4 py-6 text-center"
            data-testid="processo-modal-placeholder"
        >
            <span
                className="flex h-11 w-11 items-center justify-center rounded-xl"
                style={{
                    background: withAlpha(COLORS.brand, 0.1),
                    color: COLORS.brand,
                }}
                aria-hidden
            >
                <FileText className="h-5 w-5" strokeWidth={1.7} />
            </span>
            <p
                className="max-w-56 font-satoshi text-sm leading-relaxed"
                style={{ color: COLORS.textDim }}
            >
                {message}
            </p>
            {children ? (
                <div className="flex w-full flex-col items-stretch gap-2">{children}</div>
            ) : null}
        </div>
    );
}

interface IProcessoModalAnexoSlotProps {
    slot: IDetalhesParteProcessoModalAnexoSlot;
    isRemoving: boolean;
    onSelect: () => void;
    onRemove: () => Promise<void>;
}

function ProcessoModalAnexoSlot({
    slot,
    isRemoving,
    onSelect,
    onRemove,
}: IProcessoModalAnexoSlotProps) {
    return (
        <div
            className={cn(
                'flex min-w-0 items-center gap-2 rounded-xl border p-2 transition-colors',
                slot.isSelected && 'ring-1 ring-celer-blue',
            )}
            style={{
                borderColor: slot.isSelected ? COLORS.brand : COLORS.line,
                background: slot.isSelected ? withAlpha(COLORS.brand, 0.06) : COLORS.paper,
            }}
            data-testid={`processo-modal-slot-${slot.slotKey}`}
        >
            <span
                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg"
                style={{
                    background: withAlpha(COLORS.brand, 0.1),
                    color: COLORS.brand,
                }}
                aria-hidden
            >
                <Paperclip className="h-3.5 w-3.5" />
            </span>
            <span className="min-w-0 flex-1">
                <span
                    className="block truncate font-satoshi text-xs font-semibold"
                    style={{ color: COLORS.text }}
                >
                    {slot.displayName}
                </span>
                <span
                    className="block font-satoshi text-[10px] font-bold uppercase tracking-[0.08em]"
                    style={{ color: COLORS.textDim }}
                >
                    {slot.extensionLabel}
                </span>
            </span>
            <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7 shrink-0"
                style={{ color: slot.isSelected ? COLORS.brand : COLORS.textDim }}
                aria-label={`Visualizar ${slot.fileName}`}
                aria-pressed={slot.isSelected}
                onClick={onSelect}
            >
                <Eye className="h-3.5 w-3.5" strokeWidth={1.8} />
            </Button>

