} from '@/design-system';
import { cn } from '@/lib/utils';
import { FileText, Loader2, Paperclip, Upload, X } from 'lucide-react';
import type { ChangeEvent, ReactNode } from 'react';
import type {
    IDetalhesParteCertidaoModalAnexoSlot,
    IDetalhesParteCertidaoModalViewProps,
    TDetalhesParteCertidaoModalResultadoIconKey,
} from '../../interfaces/detalhesParteCertidaoModal';
import {
    CERTIDAO_RESULTADO_ICONS,
    resolveCertidaoResultadoColor,
} from '../../utils/certidaoResultadoVisual';

const CERTIDAO_MODAL_PREVIEW_WIDTH = 420;

interface IDetalhesParteCertidaoModalHeaderProps {
    certidaoNome: string;
    resultadoLabel: string;
    resultadoIconKey: TDetalhesParteCertidaoModalResultadoIconKey;
    valorDividaLabel: string | null;
    onClose: () => void;
}

function DetalhesParteCertidaoModalHeader({
    certidaoNome,
    resultadoLabel,
    resultadoIconKey,
    valorDividaLabel,
    onClose,
}: IDetalhesParteCertidaoModalHeaderProps) {
    const Icon = CERTIDAO_RESULTADO_ICONS[resultadoIconKey];
    const color = resolveCertidaoResultadoColor(resultadoIconKey);

    return (
        <ProductDialogHeader className="flex flex-row items-center gap-3 space-y-0 px-[18px] py-[15px]">
            <span
                className="flex h-[30px] w-[30px] shrink-0 items-center justify-center rounded-lg"
                style={{
                    background: withAlpha(color, 0.14),
                    color,
                }}
                data-testid="certidao-modal-resultado-icon"
                aria-hidden
            >
                <Icon size={16} strokeWidth={1.8} />
            </span>

            <div className="min-w-0 flex-1">
                <ProductDialogTitle className="truncate font-satoshi text-sm font-bold leading-tight">
                    {certidaoNome}
                </ProductDialogTitle>
                <ProductDialogDescription
                    className="mt-0.5 text-[11px] leading-none"
                    style={{ color: COLORS.textDim }}
                >
                    {resultadoLabel}
                </ProductDialogDescription>
            </div>

            <div className="flex shrink-0 items-center gap-3">
                {valorDividaLabel ? (
                    <div className="text-right" data-testid="certidao-modal-valor-divida">
                        <p
                            className="font-satoshi text-[10px] font-bold uppercase tracking-[0.06em]"
                            style={{ color: COLORS.textDim }}
                        >
                            Valor da dívida
                        </p>
                        <p
                            className="mt-0.5 font-satoshi text-[13px] font-semibold tabular-nums"
                            style={{ color: COLORS.text }}
                        >
                            {valorDividaLabel}
                        </p>
                    </div>
                ) : null}

                <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-8 w-8 shrink-0 text-muted-foreground hover:text-foreground"
                    aria-label="Fechar"
                    onClick={onClose}
                >
                    <X className="h-4 w-4" strokeWidth={1.8} />
                </Button>
            </div>
        </ProductDialogHeader>
    );
}

interface ICertidaoModalUploadActionProps {
    id: string;
    label: string;
    accept: string;
    isUploading: boolean;
    onUpload: (file: File) => Promise<void>;
}

function CertidaoModalUploadAction({
    id,
    label,
    accept,
    isUploading,
    onUpload,
}: ICertidaoModalUploadActionProps) {
    async function onFileChange(event: ChangeEvent<HTMLInputElement>) {
        const input = event.currentTarget;
        const file = input.files?.[0];
        input.value = '';

        if (file) await onUpload(file);
    }

    return (
        <label
            htmlFor={id}
            aria-disabled={isUploading}
            className={cn(
                'inline-flex h-9 cursor-pointer items-center justify-center gap-2 rounded-lg border px-3 font-satoshi text-xs font-semibold transition-colors',
                isUploading
                    ? 'pointer-events-none opacity-60'
                    : 'hover:border-celer-blue hover:text-celer-blue',
            )}
            style={{ borderColor: COLORS.line, color: COLORS.text }}
        >
            <input
                id={id}
                type="file"
                accept={accept}
                disabled={isUploading}
                className="sr-only"
                onChange={onFileChange}
            />
            {isUploading ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" aria-hidden />
            ) : (
                <Upload className="h-3.5 w-3.5" aria-hidden />
            )}
            {label}
        </label>
    );
}

interface ICertidaoModalPlaceholderProps {
    message: string;
    children?: ReactNode;
}

function CertidaoModalPlaceholder({ message, children }: ICertidaoModalPlaceholderProps) {
    return (
        <div
            className="flex min-h-[310px] flex-col items-center justify-center gap-4 px-6 py-10 text-center"
            data-testid="certidao-modal-placeholder"
        >
            <span
                className="flex h-11 w-11 items-center justify-center rounded-xl"
                style={{
                    background: withAlpha(COLORS.brand, 0.1),
                    color: COLORS.brand,
                }}
                aria-hidden
            >
                <FileText className="h-5 w-5" strokeWidth={1.7} />
            </span>
            <p
                className="max-w-sm font-satoshi text-sm leading-relaxed"
                style={{ color: COLORS.textDim }}
            >
                {message}
            </p>
            {children}
        </div>
    );
}

interface ICertidaoModalAnexoSlotProps {
    slot: IDetalhesParteCertidaoModalAnexoSlot;
