'use client';

import { useEffect, useState } from 'react';
import { FileText, Loader2, Maximize2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { PdfDocumentViewer } from '@/components/Modals/PdfDocumentViewer';
import { fetchDocumentBlob } from '@/functions/download/download-blob';
import {
  isImageNexoFile,
  isPdfNexoFile,
} from '@/services/nexo/nexo-file-preview';
import type { NexoDriveItem } from '@/services/nexo/nexo-api';
import { nexoApi } from '@/services/nexo/nexo-api';
import { cn } from '@/lib/utils';
import {
  integraDocumentRoomChromeClass,
  integraMutedTextClass,
} from './integra-styles';

interface IntegraDocumentRoomInlinePreviewProps {
  file: NexoDriveItem;
  onOpenFocus: () => void;
  /** Internal room allows download; public/external should pass false. */
  canDownload?: boolean;
  /** Override stream URL (public Due preview via /api/public/.../preview/). */
  streamUrlOverride?: string;
}

/**
 * Preview embutido na Sala — mesmo leitor do modo foco, limitado ao container.
 */
export function IntegraDocumentRoomInlinePreview({
  file,
  onOpenFocus,
  canDownload = true,
  streamUrlOverride,
}: IntegraDocumentRoomInlinePreviewProps) {
  const streamUrl = streamUrlOverride ?? nexoApi.streamUrl(file.id);
  const isPdf = isPdfNexoFile(file);
  const isImage = isImageNexoFile(file);

  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [loadingFile, setLoadingFile] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let objectUrl: string | null = null;

    setLoadError(null);
    setImageUrl(null);

    if (!isImage) return;

    setLoadingFile(true);
    fetchDocumentBlob(streamUrl)
      .then((blob) => {
        objectUrl = URL.createObjectURL(blob);
        if (!cancelled) setImageUrl(objectUrl);
      })
      .catch((err) => {
        if (!cancelled) {
          setLoadError(
            err instanceof Error ? err.message : 'Não foi possível carregar a imagem.'
          );
        }
      })
      .finally(() => {
        if (!cancelled) setLoadingFile(false);
      });

    return () => {
      cancelled = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [streamUrl, isImage, file.id]);

  if (!isPdf && !isImage) {
    return (
      <div
        className={cn(
          'relative flex min-h-[360px] flex-1 flex-col items-center justify-center gap-3 px-6',
          integraDocumentRoomChromeClass()
        )}
      >
        <FileText className="size-10 text-celer-muted/40" />
        <p className={cn('text-sm', integraMutedTextClass())}>
          Pré-visualização inline indisponível para este formato.
        </p>
        <Button type="button" variant="outline" size="sm" className="gap-1.5" onClick={onOpenFocus}>
          <Maximize2 className="size-3.5" />
          Abrir no visualizador
        </Button>
      </div>
    );
  }

  if (isPdf) {
    return (
      <PdfDocumentViewer
        active
        fileUrl={streamUrl}
        fileName={file.name}
        canDownload={false}
        variant="embedded"
        className={cn('min-h-0 flex-1 border-0', integraDocumentRoomChromeClass())}
        showKeyboardHints
      />
    );
  }

  if (loadingFile) {
    return (
      <div
        className={cn(
          'flex min-h-[360px] flex-1 items-center justify-center gap-2 text-sm',
          integraDocumentRoomChromeClass(),
          integraMutedTextClass()
        )}
      >
        <Loader2 className="size-4 animate-spin" />
        Carregando documento…
      </div>
    );
  }

  if (loadError) {
    return (
      <div
        className={cn(
          'flex min-h-[360px] flex-1 flex-col items-center justify-center gap-3 px-6',
          integraDocumentRoomChromeClass()
        )}
      >
        <FileText className="size-10 text-celer-muted/40" />
        <p className={cn('max-w-sm text-center text-sm', integraMutedTextClass())}>{loadError}</p>
        <Button type="button" variant="outline" size="sm" className="gap-1.5" onClick={onOpenFocus}>
          <Maximize2 className="size-3.5" />
          Abrir no modo foco
        </Button>
      </div>
    );
  }

  return (
    <div
      className={cn(
        'relative flex min-h-0 flex-1 flex-col items-center justify-center overflow-auto p-5',
        integraDocumentRoomChromeClass()
      )}

