'use client';

import { format, formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { FileText, Download, Calendar, Trash2, Plus, Loader, BookOpenText } from 'lucide-react';
import { Card, CardContent, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { Documento } from '@/interfaces/IDocumento';
import { useMutation } from '@tanstack/react-query';
import { deleteDocument } from '@/services/documentos';
import queryClient from '@/utils/queryClient';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { QueryKeys } from '@/constants/query-keys';
import { PDFViewerModal } from '../Modals/PDFViewerModal';
import { useState, useTransition } from 'react';
import { downloadFile } from '@/functions/downloadFile';

interface DocumentCardProps {
    document: Documento;
    workflowID?: string;
    className?: string;
}

export function DocumentCard({ document, workflowID, className }: DocumentCardProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [isDownloading, downloadPDFTransition] = useTransition();
    const fileUrl = document.download_url || document.stream_url || '';
    const hasFileUrl = Boolean(fileUrl);

    const [ano, mes, dia] = document.data_documento.split('-').map(Number);
    const data = new Date(ano, mes - 1, dia);

    const handleDownloadPDF = () => {
        downloadPDFTransition(async () => {
            try {
                if (!hasFileUrl) {
                    sendToastMessage({
                        title: 'Documento sem arquivo disponível.',
                        type: 'error',
                    });
                    return;
                }
                await downloadFile(document);
            } catch (error) {
                console.error('Erro ao baixar PDF:', error);
                sendToastMessage({
                    title: 'Erro ao baixar documento.',
                    type: 'error',
                });
            }
        });
    };

    const deleteDocumentMutation = useMutation({
        mutationFn: () => deleteDocument(document.id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: [QueryKeys.esteira.esteira, workflowID] });
            sendToastMessage({
                title: 'Documento excluído com sucesso!',
                type: 'success',
            });
        },
        onError: () => {
            sendToastMessage({
                title: 'Erro ao excluir documento.',
                type: 'error',
            });
        },
    });

    return (
        <Card className={cn('flex h-full flex-col overflow-hidden', className)}>
            <div className="group relative flex h-48 w-full items-center justify-center bg-gray-100 dark:bg-gray-700">
                <Button
                    variant={'secondary'}
                    size={'icon'}
                    className="absolute right-1 top-1 z-10 text-red-400"
                    onClick={() => deleteDocumentMutation.mutate()}
                    disabled={deleteDocumentMutation.isPending}
                >
                    {deleteDocumentMutation.isPending ? (
                        <Loader className="animate-spin">...</Loader>
                    ) : (
                        <Trash2 />
                    )}
                </Button>
                <div className="relative flex h-40 w-32 flex-col rounded-md bg-white shadow-md dark:bg-gray-500">
                    <div className="flex flex-1 items-center justify-center p-4">
                        <FileText className="h-8 w-8 text-blue-500" />
                    </div>
                    <div className="truncate rounded-b-md bg-gray-200 p-2 text-center text-xs dark:bg-gray-500">
                        {document.nome.split('.')[0]}
                    </div>
                </div>

                <div className="absolute inset-0 hidden items-center justify-center gap-2 bg-black/70 group-hover:flex">
                    <Button
                        size="sm"
                        variant="outline"

