import type { BrokerDocumentCatalogItem } from '@/functions/broker/groupBrokerDocumentCatalog';
import { GavetaDocumentoRow } from './GavetaDocumentoRow';

interface GavetaDocumentosGroupProps {
    title: string;
    items: BrokerDocumentCatalogItem[];
    esteiraId: number;
    loadingStates: ReturnType<typeof useBrokerDocumentPanel>['loadingStates'];
    onUpload: ReturnType<typeof useBrokerDocumentPanel>['docFunctions']['handleDoc'];
    onChangeStatus: ReturnType<typeof useBrokerDocumentPanel>['docFunctions']['changeDocStatus'];
    onDownload: ReturnType<typeof useBrokerDocumentPanel>['docFunctions']['downloadDoc'];
}

export function GavetaDocumentosGroup({
    title,
    items,
    esteiraId,
    loadingStates,
    onUpload,
    onChangeStatus,
    onDownload,
}: GavetaDocumentosGroupProps) {
    if (items.length === 0) return null;

    return (
        <section>
            <h3 className="text-celer-muted mb-2 text-[10px] font-bold uppercase tracking-[0.2em]">
                {title}
            </h3>
            <div className="flex flex-col gap-2">
                {items.map((item) => (
                    <GavetaDocumentoRow
                        key={item.id}
                        item={item}
                        esteiraId={esteiraId}
                        loadingStates={loadingStates}
                        onUpload={onUpload}
                        onChangeStatus={onChangeStatus}
                        onDownload={onDownload}
                    />
                ))}
            </div>
        </section>
    );
}

