'use client';

import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import type { TRessalvaConclusao } from '../../../types/dueItem';
import { useViewModelAnaliseRessalvasIntegraModal } from '../../../ViewModels/DueIntegra/useViewModelAnaliseRessalvasIntegraModal';
import { AnaliseRessalvasIntegraModalView } from './AnaliseRessalvasIntegraModalView';

export interface IAnaliseRessalvasIntegraModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    ressalvas: TRessalvaConclusao[];
}

export function AnaliseRessalvasIntegraModal({
    open,
    onOpenChange,
    ressalvas,
}: IAnaliseRessalvasIntegraModalProps) {
    const viewModel = useViewModelAnaliseRessalvasIntegraModal({ open, ressalvas });

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="flex min-h-[80vh] w-[90vw] max-w-[90vw] max-h-[90vh] flex-col gap-0 overflow-hidden p-0">
                <DialogHeader className="shrink-0 border-b border-celer-line px-6 py-4">
                    <DialogTitle>Ressalvas do Parecer</DialogTitle>
                    <DialogDescription>{viewModel.ui.ressalvasCountLabel}</DialogDescription>
                </DialogHeader>

                <AnaliseRessalvasIntegraModalView
                    ui={viewModel.ui}
                    handlers={viewModel.handlers}
                />
            </DialogContent>
        </Dialog>
    );
}

